  js("window.checkDone=false;window.checkFailure='';(async()=>{try{const boot=await(await fetch('/api/bootstrap')).json();const p=boot.profiles.find(p=>p.example);const r=await api09('unlock',{id:p.id});token=r.token;profile09=r.profile;w=Paper.migrate(r.state);saved=Paper.clone(w);revision=r.revision;native=true;dirty=true;w.characters[0].notes='Android persistence check';if(!await save())throw Error(lastError);await lock09();await new Promise(r=>setTimeout(r,1600));const r2=await api09('unlock',{id:p.id});if(r2.state.characters[0].notes!=='Android persistence check')throw Error('Save was not persisted');token=r2.token;const reset=await api09('example-reset');if(!reset.state.characters[0].notes.includes('original sample'))throw Error('Reset failed');const out=Paper.exportCharacter(reset.state.characters[0],reset.state,{context:'game'}).text;if(!out.includes('Narrative use:')||out.includes('Private creator note'))throw Error('Game/privacy failed');w=Paper.migrate(reset.state);saved=Paper.clone(w);revision=reset.revision;profile09=r2.profile;ui.id=null;ui.page='home';render();window.checkVersion=PaperRelease.version;}catch(e){window.checkFailure=e.message}finally{window.checkDone=true}})()");
  for(int n=0;n<120;n++){if("true".equals(js("window.checkDone")))break;Thread.sleep(500);}
