  js("PaperNative.save('test.txt','text/plain',btoa('Character Paper native export check'))");
  for(int n=0;n<60&&!exported.exists();n++)Thread.sleep(100);
  require(exported.exists()&&new String(java.nio.file.Files.readAllBytes(exported.toPath()),"UTF-8").equals("Character Paper native export check"),"Native document export failed");removeMonitor(monitor);exported.delete();
  ActivityMonitor picker=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent intent){if(Intent.ACTION_OPEN_DOCUMENT.equals(intent.getAction()))return new ActivityResult(Activity.RESULT_OK,new Intent().setData(Uri.parse("content://studio.anva.characterpaper.tests.files/sample")));return null;}};addMonitor(picker);
