  int[] pos=new int[2];runOnMainSync(()->web.getLocationOnScreen(pos));float density=activity.getResources().getDisplayMetrics().density;long tapTime=SystemClock.uptimeMillis();sendPointerSync(android.view.MotionEvent.obtain(tapTime,tapTime,android.view.MotionEvent.ACTION_DOWN,pos[0]+40*density,pos[1]+35*density,0));sendPointerSync(android.view.MotionEvent.obtain(tapTime,tapTime+50,android.view.MotionEvent.ACTION_UP,pos[0]+40*density,pos[1]+35*density,0));
  for(int n=0;n<60;n++){if(js("window.fixtureRead").contains("Character Paper"))break;Thread.sleep(100);}
  require(js("window.fixtureRead").contains("Character Paper"),"Native file picker did not return readable content");removeMonitor(picker);
  String originalUrl=js("location.href");runOnMainSync(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));Thread.sleep(700);require(originalUrl.equals(js("location.href")),"Rotation changed local page");runOnMainSync(()->activity.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT));
